<template><div class="grid gap-4 md:grid-cols-2"><el-card><template #header><span class="font-bold">{{ profile?.full_name||'Profile' }}</span></template><div class="space-y-3 text-sm"><div class="flex justify-between"><span class="text-gray-400">Username</span><span>{{ profile?.username }}</span></div><div class="flex justify-between"><span class="text-gray-400">Roles</span></div><div class="flex gap-1"><el-tag v-for="r in profile?.roles||[]" :key="r" size="small">{{ r }}</el-tag></div><div class="flex justify-between"><span class="text-gray-400">Permissions</span></div><div class="flex flex-wrap gap-1"><el-tag v-for="p in profile?.permissions||[]" :key="p" size="small" type="info">{{ p }}</el-tag></div></div></el-card><el-card><template #header>Skills</template><div v-if="skills.length"><div v-for="s in skills" :key="s.skill_id" class="flex items-center gap-3 py-2 border-b last:border-0"><span class="w-24 text-sm">{{ s.skill_name }}</span><el-progress :percentage="s.proficiency_level*20" :color="s.is_core?'#f59e0b':undefined" :stroke-width="12" /><span class="text-xs text-gray-400 w-16">{{ s.proficiency_level }}/5</span></div></div><div v-else class="text-gray-400 text-center py-4">No skills data</div></el-card></div></template><script setup lang="ts">import {ref,onMounted}from 'vue';import {getProfile,getEmployeeSkills}from '@/api/hrms';const emit=defineEmits(['update-title']);emit('update-title','Employee Profile');const profile=ref<any>({});const skills=ref<any[]>([]);onMounted(async()=>{try{const r:any=await getProfile();profile.value=r.data||{};const s:any=await getEmployeeSkills(profile.value.user_id||1);skills.value=s.data||[]}catch(e){}})</script>
